import itertools

def can_generate_all(n, initial_vectors):
    basis = []
    for i in range(n):
        vec = [0] * n
        vec[i] = 1
        basis.append(tuple(vec))
        vec[i] = -1
        basis.append(tuple(vec))
    basis.append(tuple([0]*n))

    reachable = set(initial_vectors)
    queue = list(initial_vectors)

    max_iterations = 1000
    count = 0
    while queue and count < max_iterations:
        count += 1
        v = queue.pop(0)

        new_reachable = []
        for r in reachable:
            v_add = tuple(x + y for x, y in zip(v, r))
            if all(-2 <= x <= 2 for x in v_add):
                if v_add not in reachable:
                    new_reachable.append(v_add)
            v_max = tuple(max(x, y) for x, y in zip(v, r))
            if all(-2 <= x <= 2 for x in v_max):
                if v_max not in reachable:
                    new_reachable.append(v_max)

        for nr in new_reachable:
            reachable.add(nr)
            queue.append(nr)

    return all(b in reachable for b in basis)

