for v1 in itertools.product([-1, 0, 1], repeat=2):
    for v2 in itertools.product([-1, 0, 1], repeat=2):
        if v1 == v2: continue
        if can_generate_all(2, [v1, v2]):
            print(f"Found s=2 for n=2 with {v1} and {v2}")
            break
    else:
        continue
    break
else:
